import{_ as i,l as o,o as e,c as n,v as l,p as s,x as t,d as E,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"红队评测","description":"","frontmatter":{"title":"红队评测","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/red-team-eval.md","filePath":"llm/red-team-eval.md","lastUpdated":1789023840000}'),A={name:"llm/red-team-eval.md"};function h(m,a,_,c,u,B){const r=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="红队评测" tabindex="-1">红队评测 <a class="header-anchor" href="#红队评测" aria-label="Permalink to &quot;红队评测&quot;">​</a></h1><div class="epigraph"><p>红队要的是覆盖失败模式，不是覆盖训练集。一次「没找着」只说明这次的时间与权限不够，不能写成安全证明。</p><footer>—— Ganguli 等对人红队的报告；Perez 等用模型辅助红队的协议取向</footer></div><p><a href="/llm/dangerous-capability-eval">上一课</a>把门禁写成专家门槛。红队评测问另一面：在<strong>声明已拒绝的行为</strong>上，对抗者能否找漏洞。<a href="/llm/jailbreak">越狱</a>课写过攻击形态的存在；本课写评测怎么抽样、怎么计分、怎么不把剧本变成公开教程。缺口是覆盖率，不是新的越狱分类学。后课偏见基准处理的是分布性伤害，与「单次突破防护」不同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Ganguli 等人展示人红队能收集多样有害成功案例，供后续拒答训练。Perez 等人展示语言模型可以规模化生成攻击性提示，降低人时。评测上的陷阱：用固定公开越狱表当回归，很快被训穿，分数变好但新文风仍成功。静态表是回归，不是红队。</p><p>第二陷阱是把红队成功率当唯一 KPI：防御方会过拒，伤害覆盖下降但可用性崩溃。应分列：突破率、过拒率、严重度，以及是否在工具/多轮/间接注入条件下更易突破。</p><p><span class="marginnote">自动化红队会把生成器自己的偏见写成「攻击分布」。人仍要抽检新簇，否则评测在刷生成器的众数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>协议：范围（哪些危害族）；访问（是否给工具、是否多轮）；时间盒；成功判据（完成有害目标的哪一步算成功，由专家定义）；记录与最小留存。公开报告只给族级统计与修复项，不给可复制的成功提示。内部保留样本供回归，回归集与探索集分开，探索集持续轮换。</p><p>与部署监控衔接：线上新文风应回流成下一轮红队种子，而不是只加一条过滤器。</p>',10)),(e(),s(p,null,{default:t(()=>[d(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCOPE%5B%22%E5%8D%B1%E5%AE%B3%E6%97%8F%E4%B8%8E%E8%AE%BF%E9%97%AE%22%5D%20--%3E%20HUM%5B%22%E4%BA%BA%E7%BA%A2%E9%98%9F%22%5D%0A%20%20SCOPE%20--%3E%20AUTO%5B%22%E6%A8%A1%E5%9E%8B%E8%BE%85%E5%8A%A9%E6%8E%A2%E7%B4%A2%22%5D%0A%20%20HUM%20--%3E%20SEV%5B%22%E4%B8%A5%E9%87%8D%E5%BA%A6%E4%B8%8E%E7%AA%81%E7%A0%B4%E7%8E%87%22%5D%0A%20%20AUTO%20--%3E%20SEV%0A%20%20SEV%20--%3E%20FIX%5B%22%E4%BF%AE%E5%A4%8D%E4%B8%8E%E8%BF%87%E6%8B%92%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>防护是训练过的边界，红队是在边界上做对抗搜索。搜索预算（人时、模型调用、轮数）决定「没找着」的含义。预算应写入报告，否则无法比较两版模型。成功判据若只看「模型说出了违禁词」，会漏掉工具链上的实际危害、也会把文学引用算进去——判据必须绑定后果。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供越狱配方或绕过产品安全的特征。下一课改看静态与半静态的偏见/毒性基准：它们测的是分布，不是对抗搜索的可达集。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>红队是有预算的对抗搜索；静态越狱表只是回归。</li><li>分列突破、过拒、严重度；公开报告不附可复制剧本。</li><li>「没找着」不等于安全证明。</li><li>出处：Ganguli 等人红队；Perez 等模型辅助红队。</li></ul>',6))])}const T=i(A,[["render",h]]);export{P as __pageData,T as default};
